import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Mail, Lock, LogIn } from 'lucide-react';
import api from '../../api/api';

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      // Chamada para o seu backend Node.js
      const { data } = await api.post('/auth/login', { email, password });

      // Salva Token e Dados do Usuário
      localStorage.setItem('@SobrancelhaExpress:token', data.token);
      localStorage.setItem('@SobrancelhaExpress:user', JSON.stringify(data.user));

      // Redirecionamento Inteligente baseado no ROLE
      if (data.user.role === 'admin') {
        navigate('/professional/dashboard');
      } else {
        navigate('/cliente/agendar');
      }

    } catch (err) {
      setError(err.response?.data?.message || 'E-mail ou senha incorretos');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.loginBox}>
        <div style={styles.header}>
          <h1 style={styles.logoText}>Sobrancelha<span>Express</span></h1>
          <p style={styles.subtitle}>Bem-vinda de volta!</p>
        </div>

        {error && <div style={styles.errorBanner}>{error}</div>}

        <form onSubmit={handleLogin} style={styles.form}>
          <div style={styles.inputGroup}>
            <Mail size={20} color="#D988B3" />
            <input
              type="email"
              placeholder="E-mail"
              style={styles.input}
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>

          <div style={styles.inputGroup}>
            <Lock size={20} color="#D988B3" />
            <input
              type="password"
              placeholder="Senha"
              style={styles.input}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <button type="submit" disabled={loading} style={styles.button}>
            {loading ? 'Entrando...' : (
              <>
                <span>Entrar</span>
                <LogIn size={20} />
              </>
            )}
          </button>
        </form>
      </div>
    </div>
  );
}

const styles = {
  container: {
    height: '100vh',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: '#FFF6FB', // Mesmo fundo do seu layout profissional
  },
  loginBox: {
    background: '#fff',
    padding: '40px',
    borderRadius: '20px',
    boxShadow: '0 10px 25px rgba(217, 136, 179, 0.2)',
    width: '100%',
    maxWidth: '400px',
    textAlign: 'center'
  },
  logoText: {
    color: '#333',
    fontSize: '24px',
    fontWeight: '700',
    marginBottom: '5px'
  },
  subtitle: {
    color: '#666',
    fontSize: '14px',
    marginBottom: '30px'
  },
  form: {
    display: 'flex',
    flexDirection: 'column',
    gap: '15px'
  },
  inputGroup: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    background: '#F9F9F9',
    padding: '12px 15px',
    borderRadius: '10px',
    border: '1px solid #eee'
  },
  input: {
    border: 'none',
    background: 'transparent',
    outline: 'none',
    width: '100%',
    fontSize: '16px'
  },
  button: {
    background: '#D988B3',
    color: 'white',
    border: 'none',
    padding: '15px',
    borderRadius: '10px',
    fontSize: '16px',
    fontWeight: '600',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '10px',
    marginTop: '10px',
    transition: '0.3s'
  },
  errorBanner: {
    background: '#fee2e2',
    color: '#dc2626',
    padding: '10px',
    borderRadius: '8px',
    marginBottom: '20px',
    fontSize: '14px'
  }
};
